S=/private/tmp/claude-501/-Users-smaschek-dev-paigasus-paigasus-helikon/9134c40b-e34c-4e03-aba6-d1c143283d73/scratchpad
python3 -I - "$S" <<'PY'
import json,sys,re
S=sys.argv[1]
m=json.load(open(f"{S}/sma838-meta.json"))
pk={p['name']:p for p in m['packages']}
pubset={n for n,p in pk.items() if p.get('publish')!=[]}
reg={'paigasus-helikon-core':'0.7.0','paigasus-helikon-macros':'0.2.6'}
topub={n for n in pubset if n not in reg}
def caret_ok(req,ver):
    r=req.lstrip('^=').strip(); rv=[int(x) for x in r.split('.')]+[0]*(3-len(r.split('.')))
    v=[int(x) for x in ver.split('.')]
    if v< rv: return False
    if rv[0]>0: return v[0]==rv[0]
    if rv[1]>0: return v[0]==0 and v[1]==rv[1]
    return v[:3]==rv
edges={}; problems=[]; dev=[]
for n in sorted(pubset):
    p=pk[n]; edges[n]=set()
    for d in p['dependencies']:
        if d['name'] not in pk: continue
        if d['kind']=='dev':
            dev.append((n,d['name'],d['req'],'path' in d and d.get('path') is not None))
            if d['req']!='*': problems.append(f"dev-dep with version req {n}->{d['name']} {d['req']}")
            continue
        t=d['name']; tv=pk[t]['version']
        ok=caret_ok(d['req'],tv)
        edges[n].add(t)
        src='registry' if t in reg else 'same run'
        print(f"  {n} -> {t} req {d['req']} (kind={d['kind'] or 'normal'}, opt={d['optional']}) target {tv} [{src}] {'OK' if ok else 'MISMATCH'}")
        if not ok: problems.append(f"{n}->{t} {d['req']} vs {tv}")
        if t not in pubset: problems.append(f"{n} depends on unpublishable {t}")
# topo order (Kahn, alphabetical tiebreak)
order=[]; done=set(reg)
rem=set(topub)
while rem:
    ready=sorted(n for n in rem if edges[n]-{x for x in edges[n] if x in done}==set())
    if not ready: problems.append('cycle '+str(rem)); break
    for n in ready: order.append((n,pk[n]['version'],sorted(edges[n]))); done.add(n); rem.discard(n)
print("\nTOPO ORDER (deps first):")
for i,(n,v,e) in enumerate(order,1): print(f"{i:2}. {n} {v}   deps: {', '.join(x.replace('paigasus-helikon-','') for x in e) or '-'}")
print("\nDEV-DEPS (internal):"); [print("  ",x) for x in dev]
print("\nPROBLEMS:",problems or 'none')
PY

